var state = { sec:"teoria", tema:"mapa", openGen:null };
var opts  = { comentarios:true, dobles:true, tp1:false };
var valores = {};          // valores editados por generador: key = tema|gen|campo
// -- localStorage con try/catch (R10) --
function saveState(){
  try{
    localStorage.setItem("superdai", JSON.stringify({ state:state, opts:opts, valores:valores }));
  }catch(e){ /* si falla, funciona igual */ }
}
function loadState(){
  try{
    var s = JSON.parse(localStorage.getItem("superdai") || "null");
    if(s){
      if(s.state && s.state.sec) state.sec = s.state.sec;
      if(s.state && s.state.tema) state.tema = s.state.tema;
      if(s.opts) opts = Object.assign(opts, s.opts);
      if(s.valores) valores = s.valores;
    }
  }catch(e){}
}

// -- utilidades de escape/formato --
function escHTML(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function inlineFmt(t){
  var s=escHTML(t);
  s=s.replace(/`([^`]+)`/g, function(_,c){return "<code>"+c+"</code>";});
  s=s.replace(/\*\*([^*]+)\*\*/g, function(_,c){return "<strong>"+c+"</strong>";});
  return s;
}
function hl(text){
  var s=escHTML(text);
  if(!busqText) return s;
  try{
    var rx=new RegExp("("+busqText.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","gi");
    return s.replace(rx,"<mark>$1</mark>");
  }catch(e){ return s; }
}
var busqText = "";

// -- copiar con fallback (R3): copia SIEMPRE el string original --
function toast(msg){
  var t=document.getElementById("toast");
  t.textContent=msg; t.classList.add("show");
  clearTimeout(t._h); t._h=setTimeout(function(){t.classList.remove("show");},1500);
}
function doCopy(txt){
  var ok=false;
  try{
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(function(){toast("✅ ¡Copiado!");},
        function(){legacyCopy(txt);});
      return;
    }
  }catch(e){}
  legacyCopy(txt);
  function legacyCopy(t2){
    var ta=document.createElement("textarea");
    ta.value=t2; ta.style.position="fixed"; ta.style.left="-9999px";
    document.body.appendChild(ta); ta.select();
    try{ ok=document.execCommand("copy"); }catch(e){ ok=false; }
    document.body.removeChild(ta);
    toast(ok ? "✅ ¡Copiado!" : "⚠️ No se pudo copiar — seleccioná el código");
  }
}

// -- opciones globales --
function getOpts(){
  return { comentarios:opts.comentarios, doubles:opts.dobles, tp1:opts.tp1 };
}

// ---- render general ----
function temaNombres(){
  var arr=[{id:"mapa", nombre:"🗺️ Mapa de carpetas"}];
  TEORIA.forEach(function(t){arr.push({id:t.id,nombre:t.nombre});});
  return arr;
}
function renderSidebar(){
  var sb=document.getElementById("sidebar");
  var mv=document.getElementById("mobileNav");
  var names=temaNombres();
  var filtered=names.filter(function(n){
    if(!busqText) return true;
    var hay=[n.nombre];
    var t=TEORIA.find(function(x){return x.id===n.id;});
    if(t) hay.push(searchableDeTema(t));
    return hay.join(" ").toLowerCase().indexOf(busqText.toLowerCase())>=0;
  });
  var h='<div class="side-label">Temas de teoría</div>';
  filtered.forEach(function(n){
    h+='<button class="sbtn'+(n.id===state.tema?" active":"")+'" data-id="'+n.id+'" type="button">'+hl(n.nombre)+"</button>";
  });
  if(!filtered.length) h+='<p class="hint">Sin resultados para “'+escHTML(busqText)+"”.</p>";
  sb.innerHTML=h;
  Array.prototype.forEach.call(sb.querySelectorAll(".sbtn"),function(b){
    b.addEventListener("click",function(){ selectTema(b.getAttribute("data-id")); });
  });
  var mh="<option value=\"\">— Elegí un tema —</option>";
  filtered.forEach(function(n){ mh+='<option value="'+n.id+'"'+(n.id===state.tema?" selected":"")+">"+escHTML(n.nombre)+"</option>"; });
  mv.innerHTML=mh;
}
function searchableDeTema(t){
  var parts=[t.nombre,t.intro,(t.claves||[]).join(" "),(t.errores||[]).join(" "),
    (t.donde||[]).join(" ")];
  (t.codigos||[]).forEach(function(c){parts.push(c.titulo||"",c.archivo||"");});
  (t.extra||[]).forEach(function(b){ if(b.x) parts.push(b.x); });
  return parts.join(" ");
}
function selectTema(id){
  state.tema=id; state.openGen=null; saveState(); renderAll();
  document.getElementById("content").scrollIntoView({block:"start"});
}
function renderAll(){
  var names=temaNombres();
  if(!names.some(function(n){return n.id===state.tema;})) state.tema=names[0].id;
  renderSidebar();
  var c=document.getElementById("content");
  c.innerHTML="";
  if(state.tema==="mapa") renderMapa(c);
  else renderTeoria(c, TEORIA.find(function(t){return t.id===state.tema;}), state.tema);
}

// ---- TEORÍA ----
function tableHTML(tb){
  var h='<table class="neon-table"><thead><tr>'+tb.head.map(function(x){return "<th>"+inlineFmt(x)+"</th>";}).join("")+"</tr></thead><tbody>";
  tb.rows.forEach(function(r){ h+="<tr>"+r.map(function(c){return "<td>"+inlineFmt(c)+"</td>";}).join("")+"</tr>"; });
  return h+"</tbody></table>";
}
function flowHTML(f){
  return '<div class="flow">'+f.parts.map(function(p,i){
    return '<span class="fbox'+(p.lado==="BACK"?" back":"")+'">'+inlineFmt(p.t)+"</span>"+
           (p.arrow?'<span class="farrow">'+escHTML(p.arrow)+"</span>":"");
  }).join("")+"</div>";
}
function renderBloques(arr){
  var h="";
  arr.forEach(function(b){
    if(b.t==="h3") h+="<h3>"+hl(b.x)+"</h3>";
    else if(b.t==="p") h+="<p>"+inlineFmt(hl(b.x))+"</p>";
    else if(b.t==="ul") h+="<ul>"+b.items.map(function(i){return "<li>"+inlineFmt(hl(i))+"</li>";}).join("")+"</ul>";
    else if(b.t==="warn") h+='<ul class="warn-list">'+b.items.map(function(i){return "<li>"+inlineFmt(hl(i))+"</li>";}).join("")+"</ul>";
    else if(b.t==="table") h+=tableHTML(b);
    else if(b.t==="flow") h+=flowHTML(b);
    else if(b.t==="code") h+=codeBlockStr("", b.x||"", /BACK/.test(b.x||"")?"BACK":"FRONT");
    else if(b.t==="note") h+='<p class="hint" style="font-size:13px;margin:6px 0">'+inlineFmt(hl(b.x))+"</p>";
  });
  return h;
}
function codeBlockStr(title, archivo, lado){
  var badge = lado==="BACK" ? '<span class="badge back">🟣 BACK</span>'
            : lado==="FRONT" ? '<span class="badge front">🔵 FRONT</span>' : "";
  return '<div class="codeblock'+(lado==="BACK"?" back-border":"")+'"><div class="code-head"><span class="code-title">'+escHTML(title||"Código")+"</span>"
    +badge+(archivo?' <span class="code-file">· '+escHTML(archivo)+"</span>":"")
    +'</div><pre class="code"></pre></div>';
}
function collectCodigos(t){
  var list=[];
  (t.codigos||[]).forEach(function(c){list.push(c);});
  (t.extra||[]).forEach(function(b){
    if(b.t==="code"){
      var x=b.x||"";
      list.push({ titulo:"Código", archivo:x.replace(/\s*—\s*(🟣 BACK|🔵 FRONT)/,""), lado:/BACK/.test(x)?"BACK":"FRONT", codigo:b.codigo });
    }
  });
  return list;
}
function montarCodigos(root, codigos){
  var blocks=root.querySelectorAll(".codeblock");
  codigos.forEach(function(c,i){
    if(!blocks[i]) return;
    blocks[i].querySelector("pre.code").textContent=c.codigo;   // textContent: nunca innerHTML (R6)
    var btn=document.createElement("button");
    btn.className="btn-copy"; btn.type="button"; btn.textContent="📋 Copiar";
    btn.addEventListener("click",function(){ doCopy(c.codigo); });
    blocks[i].querySelector(".code-head").appendChild(btn);
  });
}
function renderTeoria(container, t, temaId){
  if(!t){ container.innerHTML='<div class="card"><h2>⚠️ Falta cargar este apunte</h2><p class="hint">No encuentro el archivo .md de este tema en el repo. No invento contenido (R12).</p></div>'; return; }
  var h='<div class="card"><h2>'+hl(t.nombre)+"</h2>";
  h+='<h3 style="margin-top:4px">Qué es / para qué sirve</h3><p>'+inlineFmt(hl(t.intro))+"</p>";
  h+='<h3>Conceptos y reglas clave</h3><ul>'+t.claves.map(function(k){return "<li>"+inlineFmt(hl(k))+"</li>";}).join("")+"</ul>";
  if(t.extra && t.extra.length){ h+=renderBloques(t.extra); }
  h+="</div>";
  if(t.donde && t.donde.length){
    h+='<div class="card"><h3 style="margin-top:0">📍 Dónde va cada archivo</h3><table class="neon-table"><thead><tr><th>Lado</th><th>Carpeta exacta</th><th>Archivo</th><th>Qué contiene</th></tr></thead><tbody>';
    t.donde.forEach(function(r){
      var lado=/🟣|BACK/.test(r[0])?"back":"front";
      h+="<tr><td><span class=\"badge "+lado+"\">"+escHTML(r[0])+"</span></td><td><code>"+escHTML(r[1])+"</code></td><td><code>"+escHTML(r[2])+"</code></td><td>"+inlineFmt(r[3])+"</td></tr>";
    });
    h+="</tbody></table></div>";
  }
  if(t.codigos && t.codigos.length){
    h+='<div class="card"><h3 style="margin-top:0">Código base</h3>';
    t.codigos.forEach(function(c){ h+=codeBlockStr(c.titulo, c.archivo, c.lado); });
    h+="</div>";
  }
  if(t.errores && t.errores.length){
    h+='<div class="card"><h3 style="margin-top:0">⚠️ Errores típicos</h3><ul class="warn-list">'
      + t.errores.map(function(e){return "<li>"+inlineFmt(hl(e))+"</li>";}).join("") + "</ul></div>";
  }
  container.innerHTML=h;
  montarCodigos(container, collectCodigos(t));
}

// ---- MAPA DE CARPETAS ----
function renderMapa(container){
  var M=MAPA_CARPETAS;
  var h='<div class="card"><h2>🗺️ Mapa de carpetas</h2><p>'+inlineFmt(M.intro)+"</p>";
  h+='<div class="tree" id="arbol">';
  M.tree.forEach(function(l,i){
    var cls = l.side==="back"?"t-back": l.side==="front"?"t-front":"t-plain";
    var click = l.info ? ' clickable" data-i="'+i+'"' : '"';
    h+='<span class="tline '+cls+click+">"+escHTML(l.line)+"</span>\n";
  });
  h+='</div><div class="tree-info" id="treeInfo">💡 Hacé clic en cualquier línea resaltada del árbol para ver qué va ahí.</div>';
  h+='<h3>Reglas para ubicar un archivo</h3><table class="neon-table"><tbody>';
  M.reglas.forEach(function(r){ h+="<tr><td>"+inlineFmt(r[0])+"</td><td>"+inlineFmt(r[1])+"</td></tr>"; });
  h+="</tbody></table>";
  h+='<h3>¿Qué va en BACK y qué en FRONT?</h3><table class="neon-table"><thead><tr><th>Tema</th><th>🟣 BACK</th><th>🔵 FRONT</th></tr></thead><tbody>';
  M.backFront.forEach(function(r){ h+="<tr><td>"+inlineFmt(r[0])+"</td><td>"+inlineFmt(r[1])+"</td><td>"+inlineFmt(r[2])+"</td></tr>"; });
  h+="</tbody></table>";
  h+='<p class="hint" style="color:var(--neon-yellow)">'+inlineFmt(M.notaPuertos)+"</p>";
  h+='<h3>Flujo de arquitectura</h3>'+renderBloques(M.flujos);
  h+='<h3>Estilos provistos por los docentes (TP1) y su destino exacto</h3><table class="neon-table"><thead><tr><th>Archivo provisto</th><th>Copiarlo a</th></tr></thead><tbody>';
  M.estilosTP1.forEach(function(r){ h+="<tr><td>"+inlineFmt(r[0])+"</td><td>"+inlineFmt(r[1])+"</td></tr>"; });
  h+="</tbody></table></div>";
  container.innerHTML=h;
  var info=document.getElementById("treeInfo");
  Array.prototype.forEach.call(container.querySelectorAll(".tline.clickable"),function(el){
    el.addEventListener("click",function(){
      var i=parseInt(el.getAttribute("data-i"),10);
      var l=MAPA_CARPETAS.tree[i];
      info.innerHTML="<b>"+escHTML(l.path||"")+"</b> — "+inlineFmt(l.info);
      Array.prototype.forEach.call(container.querySelectorAll(".tline.sel"),function(x){x.classList.remove("sel");});
      el.classList.add("sel");
    });
  });
}

