// ---- GENERADOR ----
function valKey(temaId,gid,cid){ return temaId+"|"+gid+"|"+cid; }
function fieldVal(f, temaId, gid){
  var k=valKey(temaId,gid,f.id);
  if(Object.prototype.hasOwnProperty.call(valores,k)) return valores[k];
  return f.default!==undefined?f.default:(f.tipo==="checkbox"?false:"");
}
function optLabel(o){ return typeof o==="object"? o.l : String(o); }
function optValue(o){ return typeof o==="object"? o.v : String(o); }
function renderGen(container, g, temaId){
  if(!g){ container.innerHTML='<div class="card"><h2>⚠️ Falta cargar este apunte</h2><p class="hint">No hay generadores para este tema todavía.</p></div>'; return; }
  var h='<div class="card"><h2>⚡ '+escHTML(g.nombre)+"</h2>";
  if(g.desc) h+='<p class="gen-desc">'+inlineFmt(g.desc)+"</p>";
  h+="</div>";
  container.innerHTML=h;
  if(state.openGen===null && g.generadores.length) state.openGen=g.generadores[0].id;
  g.generadores.forEach(function(gen){
    var item=document.createElement("div");
    item.className="gitem"+(state.openGen===gen.id?" open":"");
    var head=document.createElement("div");
    head.className="ghead";
    head.innerHTML='<span class="gtitle">'+escHTML(gen.titulo)+'</span><span class="hint">'+(state.openGen===gen.id?"▲":"▼")+"</span>";
    head.addEventListener("click",function(){
      state.openGen = (state.openGen===gen.id)? null : gen.id;
      saveState(); renderAll();
    });
    item.appendChild(head);
    if(state.openGen===gen.id){
      var body=document.createElement("div"); body.className="gbody";
      var split=document.createElement("div"); split.className="gen-split";
      var fields=document.createElement("div"); fields.className="gen-fields";
      var result=document.createElement("div"); result.className="gen-result";
      gen.campos.forEach(function(f){ fields.appendChild(makeField(f, gen, temaId)); });
      var actions=document.createElement("div"); actions.className="gen-actions";
      var rb=document.createElement("button"); rb.type="button"; rb.className="btn-reset"; rb.textContent="↺ Restaurar valores de ejemplo";
      rb.addEventListener("click",function(){
        gen.campos.forEach(function(f){ delete valores[valKey(temaId,gen.id,f.id)]; });
        saveState(); renderAll();
      });
      actions.appendChild(rb);
      fields.appendChild(actions);
      split.appendChild(fields); split.appendChild(result);
      body.appendChild(split); item.appendChild(body);
      var files=[];
      try{ files=gen.salida(readVals(gen,temaId), getOpts()); }
      catch(err){ result.innerHTML='<p class="field-error">⚠️ Error generando: '+escHTML(err.message)+"</p>"; }
      pintarSalida(result, files, temaId, gen);
    }
    container.appendChild(item);
  });
}
function readVals(gen, temaId){
  var v={};
  gen.campos.forEach(function(f){ v[f.id]=fieldVal(f,temaId,gen.id); });
  return v;
}
function makeField(f, gen, temaId){
  var wrap=document.createElement("div");
  var cur=fieldVal(f,temaId,gen.id);
  if(f.tipo==="checkbox"){
    wrap.className="field check";
    wrap.innerHTML='<input type="checkbox" id="fld_'+gen.id+"_"+f.id+'"'+(cur?" checked":"")+'><label for="fld_'+gen.id+"_"+f.id+'">'+escHTML(f.label)+"</label>";
    var cb=wrap.querySelector("input");
    cb.addEventListener("change",function(){ valores[valKey(temaId,gen.id,f.id)]=cb.checked; saveState(); renderAll(); });
    return wrap;
  }
  wrap.className="field";
  var lab=document.createElement("label"); lab.textContent=f.label; wrap.appendChild(lab);
  var input;
  if(f.tipo==="select"){
    input=document.createElement("select");
    f.opciones.forEach(function(o){
      var op=document.createElement("option"); op.value=optValue(o); op.textContent=optLabel(o);
      if(String(optValue(o))===String(cur)) op.selected=true;
      input.appendChild(op);
    });
    input.addEventListener("change",function(){ valores[valKey(temaId,gen.id,f.id)]=input.value; saveState(); renderAll(); });
  } else if(f.tipo==="textarea"){
    input=document.createElement("textarea"); input.rows=Math.max(2,String(cur).split("\n").length);
    input.value=cur; if(f.placeholder) input.placeholder=f.placeholder;
    input.addEventListener("input",function(){ valores[valKey(temaId,gen.id,f.id)]=input.value; saveState(); renderAll(); });
  } else {
    input=document.createElement("input");
    input.type=f.tipo==="number"?"number":"text";
    input.value=(cur===undefined||cur===null)?"":cur;
    if(f.placeholder) input.placeholder=f.placeholder;
    input.addEventListener("input",function(){ valores[valKey(temaId,gen.id,f.id)]=input.value; saveState(); renderAll(); });
  }
  wrap.appendChild(input);
  if(f.hint){ var hp=document.createElement("div"); hp.className="field-help"; hp.textContent=f.hint; wrap.appendChild(hp); }
  if(f.validate==="pascal"){
    var err=document.createElement("div"); err.className="field-error";
    var raw=String(cur||"");
    if(!raw.trim()){ err.textContent="⚠️ Vacío: se usará un nombre de ejemplo."; wrap.appendChild(err); }
    else if(raw!==pascal(raw)){ err.textContent="⚠️ Debe ser PascalCase → se corrige automáticamente a \""+pascal(raw)+"\" en el código."; wrap.appendChild(err); }
  }
  return wrap;
}
function pintarSalida(result, files, temaId, gen){
  if(!files || !files.length){ result.innerHTML='<p class="empty">Sin salida.</p>'; return; }
  result.innerHTML="";
  files.forEach(function(f){
    var bl=document.createElement("div");
    bl.className="codeblock"+(f.lado==="BACK"?" back-border":"");
    var head=document.createElement("div"); head.className="code-head";
    var badgeTxt = f.lado==="BACK" ? "🟣 BACK" : f.lado==="FRONT" ? "🔵 FRONT" : f.lado;
    var bs=document.createElement("span"); bs.className="badge "+(f.lado==="BACK"?"back":"front"); bs.textContent=badgeTxt;
    var ft=document.createElement("span"); ft.className="code-file"; ft.textContent="· "+f.archivo;
    var ttl=document.createElement("span"); ttl.className="code-title"; ttl.textContent="📄";
    head.appendChild(ttl); head.appendChild(bs); head.appendChild(ft);
    var pre=document.createElement("pre"); pre.className="code"; pre.textContent=f.codigo;  // R6: textContent
    if(files.length>1){
      var b1=document.createElement("button"); b1.type="button"; b1.className="btn-copy"; b1.textContent="📋 Copiar código";
      b1.addEventListener("click",function(){ doCopy(f.codigo); });
      head.appendChild(b1);
    } else {
      var b2=document.createElement("button"); b2.type="button"; b2.className="btn-copy"; b2.textContent="📋 Copiar código";
      b2.addEventListener("click",function(){ doCopy(f.codigo); });
      head.appendChild(b2);
    }
    bl.appendChild(head); bl.appendChild(pre);
    result.appendChild(bl);
  });
  if(files.length>1){
    var all=document.createElement("button"); all.type="button"; all.className="btn-copyall"; all.textContent="📋 Copiar todo";
    all.addEventListener("click",function(){
      doCopy(files.map(function(f){
        return "// ===== "+f.archivo+"  ("+(f.lado==="BACK"?"🟣 BACK":"🔵 FRONT")+") =====\n"+f.codigo;
      }).join("\n\n"));
    });
    result.appendChild(all);
  }
}

